solutionCode:
#include <string>

std::string collapseSpaces(int year, int month, int day) {
    std::string result = std::to_string(year) + "-";
    result += (month < 10 ? "0" : "") + std::to_string(month);
    result += "-";
    result += (day < 10 ? "0" : "") + std::to_string(day);
    return result;
}
